      "options": {
        "A": "7 毫米汞柱",
        "B": "13 毫米汞柱",
        "C": "59 毫米汞柱",
        "D": "65 毫米汞柱"
      },
      "option_A": "7 毫米汞柱",
      "option_B": "13 毫米汞柱",
      "option_C": "59 毫米汞柱",
      "option_D": "65 毫米汞柱",
